SCENARIO_TESTS=['tests/test_environment.py', 'tests/test_env_scale.py', 'tests/test_avoidance.py', 'tests/test_boundary_escape.py', 'tests/test_action_opportunities.py', 'tests/test_mission.py', 'tests/test_scenario_v3.py', 'tests/test_scenario_v3_integration.py', 'tests/test_cuda_scenario_v2.py', 'tests/test_decentralized_observations.py', 'tests/test_receiver_admission.py', 'tests/test_communication.py', 'tests/test_channel_models.py', 'tests/test_obstacle_links.py', 'tests/test_propagation.py', 'tests/test_retry_recovery.py', 'tests/test_energy.py', 'tests/test_gpu_physics.py', 'tests/test_gpu_packets.py', 'tests/test_gpu_vector.py', 'tests/test_communication_trace.py', 'tests/test_communication_rendering.py', 'tests/test_feasibility.py', 'tests/test_gpu_cuda.py::CudaPacketTests', 'tests/test_gpu_cuda.py::CudaDeviceIntegrationTests::test_composed_cpu_cuda_worlds_match_identical_actions_and_reset_seeds', 'tests/test_gpu_cuda.py::CudaDeviceIntegrationTests::test_vector_follows_nondefault_torch_stream_and_waits_for_async_step', 'tests/test_gpu_cuda.py::CudaDeviceIntegrationTests::test_gpu_packet_worlds_survive_1000_vector_steps_with_checked_capacity']
SCRIPTS={'scenario_probe.py': "import json,time\nfrom copy import deepcopy\nfrom pathlib import Path\nfrom types import SimpleNamespace\nimport numpy as np\nimport torch\nfrom uav_network.configuration import load_config\nfrom uav_network.environment.gpu.vector import WarpVectorEnv\nfrom uav_network.communication.gpu.metrics import world_info\nfrom uav_network.experiments.feasibility import oracle_action\n\nout=Path('/kaggle/working'); report={'scope':'Primary 1KiB scenario, no learned policy or scientific retuning','checks':[]}\nbase=load_config('configs/comparison-20k-hybrid75-1kb.yaml')\nbase.tracking.enabled=False\ndef save(): (out/'scenario-probe.json').write_text(json.dumps(report,indent=2,allow_nan=False))\ndef invariants(v,obs,reward):\n assert obs['observation'].is_cuda and obs['state'].is_cuda\n assert bool(torch.isfinite(obs['observation']).all()) and bool(torch.isfinite(obs['state']).all())\n assert bool(torch.isfinite(reward).all())\n positions=v.s.positions.numpy(); battery=v.s.battery.numpy(); present=v.s.report_present.numpy()\n assert np.isfinite(positions).all() and (positions>=-1e-6).all() and (positions<=v.config.world.map_size_m+1e-6).all()\n assert np.isfinite(battery).all() and (battery>=0).all() and (battery<=v.config.energy.battery_capacity_j+1e-6).all()\n assert (present.sum(axis=2)*v.config.network.report_bytes<=v.config.network.buffer_bytes).all()\n assert (v.s.delivered.numpy().sum(axis=1)<=v.config.world.num_targets).all()\n assert not v.s.errors.numpy().any()\nfor count,steps in ((8,1800),(4096,16)):\n c=deepcopy(base);c.runtime.num_envs=count\n v=WarpVectorEnv(c,device='cuda:0');started=time.monotonic()\n try:\n  obs,_=v.reset(seed=44); completed=0;next_seed=100044\n  for step in range(steps):\n   a=v.random_actions(obs['observation'])\n   obs,reward,done,truncated,infos=v.step({'continuous':a.continuous,'destination':a.destination})\n   if step%25==0 or step==steps-1:invariants(v,obs,reward)\n   if bool(done.any()):\n    indices=torch.nonzero(done).flatten().cpu().tolist(); seeds=[None]*count\n    for i in indices:seeds[i]=next_seed;next_seed+=1\n    completed+=len(indices)\n    obs,_=v.reset(seed=seeds,options={'reset_mask':done.cpu().numpy()})\n  torch.cuda.synchronize()\n  report['checks'].append({'kind':'random_scenario_stress','num_envs':count,'vector_steps':steps,\n    'joint_transitions':count*steps,'max_steps':c.world.max_steps,'completed_episodes':completed,\n    'allocated_environment_bytes':v.allocated_bytes,'device':str(v.device),'seconds':time.monotonic()-started,'status':'pass'})\n  save()\n finally:v.close()\n# Privileged engineering controller: success proves a feasible trace; failure does not prove impossibility.\nreport['oracle_records']=[]\nfor seed in (44,2000000044,2000000045):\n c=deepcopy(base);c.runtime.num_envs=1\n v=WarpVectorEnv(c,device='cuda:0')\n try:\n  obs,_=v.reset(seed=seed); started=time.monotonic()\n  for step in range(c.world.max_steps):\n   s=v.s\n   view=SimpleNamespace(config=c,vector=v,positions=s.positions.numpy()[0],velocities=s.velocities.numpy()[0],\n       targets=s.targets.numpy()[0],obstacles=s.obstacles.numpy()[0],gcs=s.gcs.numpy()[0])\n   a=oracle_action(view,observation=obs['observation'][0].cpu().numpy())\n   obs,reward,done,truncated,infos=v.step({'continuous':a.continuous[None],'destination':a.destination[None]})\n   if step%50==0:invariants(v,obs,reward)\n   if bool(done[0]):break\n  info=world_info(v.s,v.p,0)\n  report['oracle_records'].append({'seed':seed,'device':str(v.device),'steps':step+1,'info':info,\n    'seconds':time.monotonic()-started,'not_a_policy_baseline':True})\n  save()\n finally:v.close()\nreport['status']='pass';save();print(json.dumps(report,indent=2,allow_nan=False))\n", 'learner_probe.py': "import gc,json,time\nfrom pathlib import Path\nimport torch\nfrom uav_network.configuration import load_config\nfrom uav_network.cloud.execution_check import check_execution\nfrom uav_network.experiments.training import train\nfrom uav_network.experiments.evaluation import evaluate,load_evaluation_policy\nout=Path('/kaggle/working');report={'preflights':[],'runtime_smokes':[]}\ndef save(): (out/'learner-probe.json').write_text(json.dumps(report,indent=2,allow_nan=False))\nfor algorithm in ('masac','matd3'):\n for pql in (False,True):\n  name=algorithm+('-pql' if pql else '-base')\n  c=load_config('configs/comparison-20k-hybrid75-1kb.yaml')\n  c.runtime.algorithm=algorithm;c.pql.enabled=pql;c.tracking.enabled=False\n  c.runtime.output_dir=str(out/(name+'-preflight'))\n  proof=check_execution(c,out/(name+'-execution.json'))\n  report['preflights'].append({'case':name,'result':proof});save()\n  gc.collect();torch.cuda.empty_cache()\n  c=load_config('configs/smoke.yaml')\n  c.runtime.algorithm=algorithm;c.pql.enabled=pql;c.tracking.enabled=False\n  c.runtime.environment_backend='warp_packet';c.runtime.device='cuda';c.runtime.replay_device='cpu'\n  c.runtime.replay_cpu_fraction=.75;c.runtime.num_envs=4;c.runtime.episodes=8\n  c.runtime.eval_seed=2000000044;c.runtime.output_dir=str(out/(name+'-train'))\n  c.pql.warmup_collection_steps=3\n  started=time.monotonic();result=train(c)\n  assert result['episodes']>=8 and result['episode_budget_complete'] is True\n  assert result['stop_reason']=='episode_budget' and result['updates']>0\n  learner,progress,source=load_evaluation_policy(result['checkpoint'])\n  assert all(torch.isfinite(p).all() for p in learner.parameters())\n  evaluation=evaluate(result['checkpoint'],episodes=1,output_dir=str(out/(name+'-evaluation')),seed=2000000044)\n  assert evaluation['episodes']==1 and evaluation['records'][0]['seed']==2000000044\n  report['runtime_smokes'].append({'case':name,'training':result,'checkpoint_load_finite':True,\n      'evaluation':evaluation,'seconds':time.monotonic()-started})\n  save();del learner;gc.collect();torch.cuda.empty_cache()\nreport['status']='pass';save();print('FOUR_CUDA_LEARNERS_PASS',flush=True)\n"}

import json,os,subprocess,sys,time,traceback
from pathlib import Path
from datetime import datetime,timezone
root=Path('/tmp/uav-cuda-audit-source')
output=Path('/kaggle/working')
receipt={'source_commit':COMMIT,'started_utc':datetime.now(timezone.utc).isoformat(),'stages':[],'status':'starting'}
def save(): (output/'cuda-audit-receipt.json').write_text(json.dumps(receipt,indent=2))
save()
try:
 subprocess.run(['git','clone','--quiet','https://github.com/truongdaoanhduy/uav_network.git',str(root)],check=True)
 subprocess.run(['git','checkout','--quiet',COMMIT],cwd=root,check=True)
 subprocess.run(['bash','setup.sh','--system-site-packages','--cloud'],cwd=root,env=dict(os.environ,PYTHON=sys.executable),check=True)
 python=str(root/'.venv/bin/python')
 subprocess.run([python,'-m','pip','install','-q','pytest','pytest-subtests','warp-lang==1.18.0'],check=True)
 env=dict(os.environ,PYTHONPATH=str(root)+':'+str(root/'tests'),MPLBACKEND='Agg',WANDB_MODE='disabled',
          HF_HUB_OFFLINE='1',CUBLAS_WORKSPACE_CONFIG=':4096:8',PYTHONUNBUFFERED='1')
 hardware=subprocess.run([python,'-c',"import json,torch; assert torch.cuda.is_available(); assert torch.cuda.device_count()==2; print(json.dumps({'torch':torch.__version__,'cuda':torch.version.cuda,'devices':[torch.cuda.get_device_name(i) for i in range(torch.cuda.device_count())],'device_count':torch.cuda.device_count()}))"],cwd=root,env=env,text=True,capture_output=True,check=True)
 receipt['hardware']=json.loads(hardware.stdout.strip().splitlines()[-1]);receipt['status']='running';save()
 subprocess.run([python,'-m','pip','freeze'],stdout=(output/'pip-freeze.txt').open('w'),check=True)
 for name,contents in SCRIPTS.items(): (output/name).write_text(contents)
 stages=[
  ('scenario-tests',[python,'-m','pytest','-q','-ra',*SCENARIO_TESTS,'--junitxml='+str(output/'scenario-tests.xml')],1800),
  ('scenario-primary-probes',[python,str(output/'scenario_probe.py')],1800),
  ('algorithm-cuda-probes',[python,str(output/'learner_probe.py')],1800),
  ('full-suite',[python,'-m','pytest','-q','-ra','tests','--junitxml='+str(output/'full-suite.xml')],3600)]
 for name,command,timeout in stages:
  started=time.monotonic();receipt['active_stage']=name;save()
  with (output/(name+'.log')).open('w') as log:
   p=subprocess.run(command,cwd=root,env=env,stdout=log,stderr=subprocess.STDOUT,timeout=timeout)
  logtail=(output/(name+'.log')).read_text(errors='replace')[-4500:]
  receipt['stages'].append({'name':name,'exit_code':p.returncode,'seconds':time.monotonic()-started,'tail':logtail});save()
  print(json.dumps(receipt['stages'][-1]),flush=True)
  if p.returncode:raise RuntimeError('Stage failed: '+name)
 receipt['status']='passed';receipt['completed_utc']=datetime.now(timezone.utc).isoformat();save()
except BaseException as e:
 receipt['status']='failed';receipt['error']=type(e).__name__+': '+str(e)
 receipt['traceback']=traceback.format_exc();save();print(json.dumps(receipt,indent=2),flush=True);raise
